import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"参照","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/references.md","filePath":"ja/language/references.md"}'),o={name:"ja/language/references.md"};function l(c,a,d,p,r,i){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="参照" tabindex="-1">参照 <a class="header-anchor" href="#参照" aria-label="Permalink to &quot;参照&quot;">​</a></h1><p>Megalo のアクションと条件は <strong>オペランド</strong> — 実行時にプレイヤー、チーム、オブジェクト、タイマー、変数を識別する値 — を取ります。このページは参照モデル、つまりオペランドの書き方と何に解決されるかを説明します。</p><h2 id="参照の型" tabindex="-1">参照の型 <a class="header-anchor" href="#参照の型" aria-label="Permalink to &quot;参照の型&quot;">​</a></h2><p>Megalo には 5 種類の型付き参照があります。</p><table tabindex="0"><thead><tr><th>型</th><th>保持するもの</th><th>例</th></tr></thead><tbody><tr><td>Player</td><td>プレイヤースロット</td><td><code>current_player</code>、<code>killer</code>、<code>none</code></td></tr><tr><td>Team</td><td>チーム</td><td><code>current_team</code>、<code>attackers</code>、<code>defenders</code>、<code>none</code></td></tr><tr><td>Object</td><td>マップオブジェクト</td><td><code>current_object</code>、<code>one_flag</code>、<code>none</code></td></tr><tr><td>Timer</td><td>カウントダウンタイマー</td><td><code>round_timer</code>、<code>current_player.game_start_vo</code></td></tr><tr><td>Number</td><td>整数値</td><td><code>my_counter</code>、<code>score_to_win_round</code>、<code>0</code></td></tr></tbody></table><p>各型に「参照なし」または「空」を意味する <code>none</code> センチネルがあります。</p><h2 id="コンテキスト参照" tabindex="-1">コンテキスト参照 <a class="header-anchor" href="#コンテキスト参照" aria-label="Permalink to &quot;コンテキスト参照&quot;">​</a></h2><p>現在の評価コンテキストと関連するエンジン状態のための組み込み参照:</p><table tabindex="0"><thead><tr><th>名前</th><th>型</th><th>可用性</th></tr></thead><tbody><tr><td><code>current_player</code></td><td>Player</td><td><code>player</code> トリガー内</td></tr><tr><td><code>current_team</code></td><td>Team</td><td><code>team</code> トリガー内</td></tr><tr><td><code>current_object</code></td><td>Object</td><td><code>object</code> / マップオブジェクトフィルタトリガー内</td></tr><tr><td><code>local_player</code></td><td>Player</td><td>常時</td></tr><tr><td><code>local_team</code></td><td>Team</td><td>常時（<code>local_player</code> を所有するチーム）</td></tr><tr><td><code>target_player</code></td><td>Player</td><td>常時（HUD ターゲットプレイヤー）</td></tr><tr><td><code>target_object</code></td><td>Object</td><td>常時（HUD ターゲットオブジェクト）</td></tr><tr><td><code>target_team</code></td><td>Team</td><td>MegaloEvolved 拡張 <code>targetTeam</code>（<code>target_player</code> を所有するチーム）</td></tr></tbody></table><p><code>current_*</code> 参照はトリガーの深さでゲートされます。その他は常に利用可能です。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">local</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">local_team</span><span class="megalo-text"> </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">attackers</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_widget_set_visibility</span><span class="megalo-text"> status_widget </span><span class="megalo-variable">local_player</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p><a href="/MegaloEvolved/beta/docs/ja/language/enums/built-in-variables">組み込み変数</a> も参照。</p><h2 id="カスタム変数参照" tabindex="-1">カスタム変数参照 <a class="header-anchor" href="#カスタム変数参照" aria-label="Permalink to &quot;カスタム変数参照&quot;">​</a></h2><p><code>variables</code> ブロックで宣言した変数は名前で参照します。メンバー変数はドット記法です。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; global variable</span></span>
<span class="line"><span class="megalo-text">action set sudden_death_condition set_to true</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; player member variable</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">is_leader set_to </span><span class="megalo-number">1</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; team member variable</span></span>
<span class="line"><span class="megalo-text">action set current_team</span><span class="megalo-operator">.</span><span class="megalo-text">goal set_to current_object</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; object member variable</span></span>
<span class="line"><span class="megalo-text">action timer_set_rate buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">phase_1_timer </span><span class="megalo-number">1</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; chained member access</span></span>
<span class="line"><span class="megalo-text">action set buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">allies_present set_to attackers_in_area</span></span></code></pre></div><h2 id="チームデザイネータ" tabindex="-1">チームデザイネータ <a class="header-anchor" href="#チームデザイネータ" aria-label="Permalink to &quot;チームデザイネータ&quot;">​</a></h2><p>チームはデザイネータ名で参照できます。</p><table tabindex="0"><thead><tr><th>デザイネータ</th><th>役割</th></tr></thead><tbody><tr><td><code>attackers</code></td><td>攻撃側チーム</td></tr><tr><td><code>defenders</code></td><td>防御側チーム</td></tr><tr><td><code>third_party</code></td><td>第 3 チーム</td></tr><tr><td><code>fourth_party</code></td><td>第 4 チーム</td></tr><tr><td><code>fifth_party</code></td><td>第 5 チーム</td></tr><tr><td><code>sixth_party</code></td><td>第 6 チーム</td></tr><tr><td><code>seventh_party</code></td><td>第 7 チーム</td></tr><tr><td><code>eighth_party</code></td><td>第 8 チーム</td></tr><tr><td><code>none</code></td><td>チームなし</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">condition if current_player</span><span class="megalo-operator">.</span><span class="megalo-text">team equal_to attackers</span></span></code></pre></div><p>チームデザイネータは <code>teams</code> ブロックで割り当てます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">teams</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">designator</span><span class="megalo-text"> </span><span class="megalo-enumMember">defenders</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">designator</span><span class="megalo-text"> </span><span class="megalo-enumMember">attackers</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="チームまたはプレイヤーターゲット" tabindex="-1">チームまたはプレイヤーターゲット <a class="header-anchor" href="#チームまたはプレイヤーターゲット" aria-label="Permalink to &quot;チームまたはプレイヤーターゲット&quot;">​</a></h2><p>一部のアクションは <strong>チームまたはプレイヤーターゲット</strong> — 特定プレイヤー、特定チーム、または全員 — を取ります。構文は <code>team &lt;team_ref&gt;</code>、<code>player &lt;player_ref&gt;</code>、または <code>everyone</code> です。完全なオペランド参照は <a href="/MegaloEvolved/beta/docs/ja/language/enums/team-or-player-target">チームまたはプレイヤーターゲット</a> を参照。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;Round started!&quot;</span></span></code></pre></div><h2 id="オーディエンス参照" tabindex="-1">オーディエンス参照 <a class="header-anchor" href="#オーディエンス参照" aria-label="Permalink to &quot;オーディエンス参照&quot;">​</a></h2><p>他のアクションは、誰に影響するかを指定する <strong>オーディエンス</strong> オペランドを取ります（可視性、ピックアップフィルタなど）。</p><table tabindex="0"><thead><tr><th>オーディエンス</th><th>意味</th></tr></thead><tbody><tr><td><code>everyone</code></td><td>全プレイヤー</td></tr><tr><td><code>allies</code></td><td>味方プレイヤー（コンテキスト相対）</td></tr><tr><td><code>enemies</code></td><td>敵プレイヤー</td></tr><tr><td><code>player</code></td><td>特定プレイヤー（続けてプレイヤー参照）</td></tr><tr><td><code>team</code></td><td>特定チーム（続けてチーム参照）</td></tr><tr><td><code>no_one</code></td><td>誰でもない</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action navpoint_set_visible current_object allies</span></span>
<span class="line"><span class="megalo-text">action set_pickup_filter one_flag enemies</span></span>
<span class="line"><span class="megalo-text">action boundary_set_visible capture_zone everyone</span></span></code></pre></div><h2 id="組み込みタイマー参照" tabindex="-1">組み込みタイマー参照 <a class="header-anchor" href="#組み込みタイマー参照" aria-label="Permalink to &quot;組み込みタイマー参照&quot;">​</a></h2><p>エンジンは <code>variables</code> ブロックで宣言しない組み込みタイマーを提供します。</p><table tabindex="0"><thead><tr><th>タイマー</th><th>説明</th></tr></thead><tbody><tr><td><code>round_timer</code></td><td>現在ラウンドの経過時間</td></tr><tr><td><code>sudden_death_timer</code></td><td>サドンデスのカウントダウン</td></tr><tr><td><code>grace_period_timer</code></td><td>ラウンド時間終了後の猶予期間</td></tr></tbody></table><p>カスタムタイマーは <code>networked timer</code> 変数として宣言し、名前またはメンバーアクセスで参照します。</p><h2 id="オブジェクト型参照" tabindex="-1">オブジェクト型参照 <a class="header-anchor" href="#オブジェクト型参照" aria-label="Permalink to &quot;オブジェクト型参照&quot;">​</a></h2><p><code>create_object</code> と <code>object_is_type</code> のオブジェクト型は、<a href="/MegaloEvolved/beta/docs/ja/language/object-lists">オブジェクトリスト</a> からの引用名を使います。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action create_object </span><span class="megalo-string">&quot;flag&quot;</span><span class="megalo-text"> at current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn set current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag never_garbage</span></span>
<span class="line"><span class="megalo-text">action create_object </span><span class="megalo-string">&quot;invis_cov_resupply_capsule&quot;</span><span class="megalo-text"> at current_object never_garbage</span></span>
<span class="line"><span class="megalo-text">condition object_is_type current_object </span><span class="megalo-string">&quot;area&quot;</span></span>
<span class="line"><span class="megalo-text">condition object_is_type current_object </span><span class="megalo-string">&quot;fireteam_1_respawn_zone&quot;</span></span></code></pre></div><h2 id="プレイヤーをオブジェクトとして扱う参照" tabindex="-1">プレイヤーをオブジェクトとして扱う参照 <a class="header-anchor" href="#プレイヤーをオブジェクトとして扱う参照" aria-label="Permalink to &quot;プレイヤーをオブジェクトとして扱う参照&quot;">​</a></h2><p>オブジェクト参照が期待される場所ではプレイヤー参照を使えます。エンジンはプレイヤーの物理ボディオブジェクトに解決します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; from simple/koth/1.txt — a player reference used as an object reference</span></span>
<span class="line"><span class="megalo-text">action for_each player</span></span>
<span class="line"><span class="megalo-text">	condition object_in_area current_player current_object</span></span>
<span class="line"><span class="megalo-text">	action timer_set_rate current_player</span><span class="megalo-operator">.</span><span class="megalo-text">time_in_hill </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">temporary object my_body current_player</span></span>
<span class="line"><span class="megalo-text">action for_each general</span></span>
<span class="line"><span class="megalo-text">	condition if my_body </span><span class="megalo-operator">!=</span><span class="megalo-text"> none</span></span>
<span class="line"><span class="megalo-text">	action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">body </span><span class="megalo-operator">=</span><span class="megalo-text"> my_body</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="文字列テーブル参照" tabindex="-1">文字列テーブル参照 <a class="header-anchor" href="#文字列テーブル参照" aria-label="Permalink to &quot;文字列テーブル参照&quot;">​</a></h2><p>アクションと要素フィールドの文字列オペランドは、<code>string_table</code> ブロックで定義した記号を参照します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action hud_post_message player current_player none invasion_title_spartan</span></span>
<span class="line"><span class="megalo-text">action player_set_objective current_player slayer_objective score_to_win_round</span></span>
<span class="line"><span class="megalo-text">action navpoint_set_text current_object nav_weapon_drop</span></span></code></pre></div><p>ソース上は引用文字列ではなく — 実行時に文字列テーブルを通じて解決される識別子参照です。文字列に <code>%</code> プレースホルダがある場合、続くオペランドがそれらのスロットを埋めます — <a href="/MegaloEvolved/beta/docs/ja/language/enums/dynamic-strings">動的文字列</a> を参照。</p><h2 id="フィルタ参照" tabindex="-1">フィルタ参照 <a class="header-anchor" href="#フィルタ参照" aria-label="Permalink to &quot;フィルタ参照&quot;">​</a></h2><p>オブジェクトフィルタオペランドは、誰がオブジェクトと相互作用できるかを識別します。</p><table tabindex="0"><thead><tr><th>フィルタ</th><th>意味</th></tr></thead><tbody><tr><td><code>all</code></td><td>全員</td></tr><tr><td><code>allies</code></td><td>味方プレイヤー／チーム</td></tr><tr><td><code>enemies</code></td><td>敵プレイヤー／チーム</td></tr><tr><td><code>no_one</code></td><td>誰でもない</td></tr><tr><td><code>none</code></td><td>フィルタなし（無効）</td></tr></tbody></table><p>リスポーン、ピックアップ、ファイアチームフィルタのアクションで使います。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_respawn_filter current_object allies</span></span>
<span class="line"><span class="megalo-text">action set_pickup_filter current_object no_one</span></span>
<span class="line"><span class="megalo-text">action set_fireteam_respawn_filter current_object all</span></span></code></pre></div><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/variable-model">変数モデル</a> — カスタム変数の宣言</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/action">action</a> — 参照がオペランドとして現れる方法</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/condition">condition</a> — 比較内の参照</li><li><a href="/MegaloEvolved/beta/docs/ja/language/object-lists">オブジェクトリスト</a> — オブジェクト型とインシデントの記号名</li></ul>`,49)])])}const _=e(o,[["render",l]]);export{g as __pageData,_ as default};
